import java.util.*;

class AutocompleteSystem {
  private static class Node {
    Map<Character, Node> next = new HashMap<>();
    Map<String, Integer> counts = new HashMap<>(); // sentences passing through this prefix
  }

  private final Node root = new Node();
  private Node cur;
  private final StringBuilder typed = new StringBuilder();

  public AutocompleteSystem(String[] sentences, int[] times) {
    for (int i = 0; i < sentences.length; i++) add(sentences[i], times[i]);
    cur = root;
  }

  public List<String> input(char c) {
    if (c == '#') {
      add(typed.toString(), 1);
      typed.setLength(0);
      cur = root;
      return new ArrayList<>();
    }
    typed.append(c);
    if (cur != null) cur = cur.next.get(c);
    if (cur == null) return new ArrayList<>();
    List<Map.Entry<String, Integer>> entries = new ArrayList<>(cur.counts.entrySet());
    entries.sort((a, b) -> !a.getValue().equals(b.getValue()) ? b.getValue() - a.getValue() : a.getKey().compareTo(b.getKey()));
    List<String> res = new ArrayList<>();
    for (int i = 0; i < Math.min(3, entries.size()); i++) res.add(entries.get(i).getKey());
    return res;
  }

  private void add(String sentence, int times) {
    Node node = root;
    for (char c : sentence.toCharArray()) {
      node = node.next.computeIfAbsent(c, k -> new Node());
      node.counts.merge(sentence, times, Integer::sum);
    }
  }
}
